-- Only the public/short number printed by the platform or generated by Pitacco may appear.
-- Never use orders.id, deliveries.id or deliveries.external_order_id in an order card.
create or replace function public.pitacco_order_public_label(p_receipt jsonb,p_source text)
returns text language plpgsql immutable set search_path to ''
as $$
declare
  r jsonb:=coalesce(p_receipt,'{}'::jsonb);
  src text:=lower(coalesce(p_source,''));
  candidate text;
begin
  if src in ('99','99food','99_food','99-food') then
    candidate:=coalesce(
      nullif(pg_catalog.btrim(r->>'display_number'),''),
      nullif(pg_catalog.btrim(r->>'external_order_number'),''),
      nullif(pg_catalog.btrim(r->>'order_number'),''),
      nullif(pg_catalog.btrim(r->>'display_id'),'')
    );
  else
    candidate:=coalesce(
      nullif(pg_catalog.btrim(r->>'display_number'),''),
      nullif(pg_catalog.btrim(r->>'external_order_number'),''),
      nullif(pg_catalog.btrim(r->>'order_number'),''),
      nullif(pg_catalog.btrim(r->>'display_id'),''),
      nullif(pg_catalog.btrim(r->>'number'),'')
    );
  end if;
  if candidate is null then return null; end if;
  -- Reject raw technical IDs and long opaque identifiers.
  if length(candidate)>24
     or candidate ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or (src in ('99','99food','99_food','99-food') and candidate ~ '^[0-9]{13,}$')
  then return null; end if;
  return candidate;
end;
$$;
revoke all on function public.pitacco_order_public_label(jsonb,text) from public,anon;
grant execute on function public.pitacco_order_public_label(jsonb,text) to authenticated,service_role;

create or replace function public.pitacco_order_phone_locator(
  p_receipt jsonb,p_private_code text,p_private_phone text,p_private_expires timestamptz
)
returns text language plpgsql stable set search_path to ''
as $$
declare
  r jsonb:=coalesce(p_receipt,'{}'::jsonb);
  phone text;
  loc text;
  expiry text;
begin
  if p_private_expires is not null and p_private_expires<=pg_catalog.now() then return null; end if;
  expiry:=coalesce(nullif(r->'customer'->'phone'->>'localizerExpiration',''),
                   nullif(r->>'phone_localizer_expiration',''));
  if expiry is not null and pg_catalog.pg_input_is_valid(expiry,'timestamp with time zone') then
    if expiry::timestamptz <= pg_catalog.now() then return null; end if;
  end if;
  loc:=coalesce(nullif(p_private_code,''),
    nullif(r->'customer'->'phone'->>'localizer',''),
    nullif(r->>'phone_localizer',''),
    nullif(r->>'localizer',''),
    nullif(r->'phone'->>'localizer','')
  );
  phone:=coalesce(nullif(p_private_phone,''),
    nullif(r->'customer'->'phone'->>'number',''),
    nullif(r->>'customer_phone',''),
    nullif(r->>'customerPhone','')
  );
  if loc is null and phone like '%,%' then
    loc:=pg_catalog.regexp_replace(pg_catalog.split_part(phone,',',2),'[^0-9]','','g');
  end if;
  loc:=pg_catalog.left(pg_catalog.regexp_replace(coalesce(loc,''),'[^0-9]','','g'),16);
  return nullif(loc,'');
end;
$$;
revoke all on function public.pitacco_order_phone_locator(jsonb,text,text,timestamptz) from public,anon;
grant execute on function public.pitacco_order_phone_locator(jsonb,text,text,timestamptz) to authenticated,service_role;

-- Courier card labels: only active, assigned, own-delivery orders.
create or replace function public.pitacco_driver_card_badges()
returns jsonb language plpgsql stable security definer set search_path to ''
as $$
declare result jsonb;
begin
  if (select auth.uid()) is null or not public.pitacco_courier_session_ready() then
    raise exception 'Sessão não autorizada' using errcode='42501';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'delivery_id',d.id,
    'public_number',public.pitacco_order_public_label(o.receipt,coalesce(o.source,d.source)),
    'localizer',public.pitacco_order_phone_locator(
       o.receipt,ct.phone_localizer,ct.phone_number,ct.phone_expires_at)
    ) order by d.created_at desc),'[]'::jsonb)
  into result
  from public.deliveries d
  join public.couriers c on c.id=d.courier_id and c.store_id=d.store_id
  left join public.orders o on o.id=d.order_id and o.store_id=d.store_id
  left join public.pitacco_delivery_customer_contacts ct
      on ct.delivery_id=d.id and ct.store_id=d.store_id
  where c.user_id=(select auth.uid()) and c.active=true
    and d.logistics_provider='loja'
    and d.status not in ('cancelada','entregue');
  return result;
end;
$$;
revoke all on function public.pitacco_driver_card_badges() from public,anon;
grant execute on function public.pitacco_driver_card_badges() to authenticated;

-- Lojista: all current orders belonging to the authorized store, never raw external IDs.
create or replace function public.pitacco_merchant_order_badges(p_store uuid)
returns jsonb language plpgsql stable security definer set search_path to ''
as $$
declare result jsonb;
begin
  if (select auth.uid()) is null or p_store is null or not exists(
    select 1 from public.stores s where s.id=p_store and (
      exists(select 1 from pitacco_private.platform_owner a where a.user_id=(select auth.uid()))
      or exists(select 1 from public.store_members m where m.store_id=s.id and m.user_id=(select auth.uid())
                   and m.role in ('gestor','lojista'))
    )
  ) then raise exception 'Loja não autorizada' using errcode='42501'; end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'order_id',o.id,
    'public_number',public.pitacco_order_public_label(o.receipt,o.source),
    'localizer',public.pitacco_order_phone_locator(
       o.receipt,ct.phone_localizer,ct.phone_number,ct.phone_expires_at)
    ) order by o.created_at desc),'[]'::jsonb)
   into result
   from (
     select id,source,receipt,created_at
       from public.orders
      where store_id=p_store
      order by created_at desc limit 150
   ) o
   left join lateral (
     select ct.phone_localizer,ct.phone_number,ct.phone_expires_at
       from public.deliveries d
       join public.pitacco_delivery_customer_contacts ct
        on ct.delivery_id=d.id and ct.store_id=d.store_id
      where d.order_id=o.id and d.store_id=p_store
      order by d.created_at desc limit 1
   ) ct on true;
  return result;
end;
$$;
revoke all on function public.pitacco_merchant_order_badges(uuid) from public,anon;
grant execute on function public.pitacco_merchant_order_badges(uuid) to authenticated;

-- Public number in full order details must be the same as in both cards.
-- Existing function has an unsafe preference for external_order_id (99Food technical ID).
-- A separate change below replaces its number expression.
